def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n == 0:
        return lista[:]
    return lista[-n:] + lista[:-n]

def a_romano(n):
    val = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'),
        (1, 'I')
    ]
    resultado = ''
    for valor, simbolo in val:
        while n >= valor:
            resultado += simbolo
            n -= valor
    return resultado

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    resultado = 0
    anterior = 0
    for char in reversed(s):
        valor = valores[char]
        if valor < anterior:
            resultado -= valor
        else:
            resultado += valor
            anterior = valor
    return resultado

