def primos(n):
    if n < 2:
        return []
    primos_list = []
    for num in range(2, n + 1):
        es_primo = True
        for divisor in range(2, int(num ** 0.5) + 1):
            if num % divisor == 0:
                es_primo = False
                break
        if es_primo:
            primos_list.append(num)
    return primos_list

