        return []
    ordenados = sorted(intervalos)
    resultado = [ordenados[0]]
    for inicio, fin in ordenados[1:]:
        if inicio <= resultado[-1][1]:
            resultado[-1] = (resultado[-1][0], max(resultado[-1][1], fin))
        else:
            resultado.append((inicio, fin))
    return resultado

def comprimir(s):
    if not s:
        return s
    resultado = []
    contador = 1
    for i in range(1, len(s)):
        if s[i] == s[i - 1]:
            contador += 1
        else:
            resultado.append(s[i - 1])
            resultado.append(str(contador))
            contador = 1
    resultado.append(s[-1])
    resultado.append(str(contador))
    comprimida = ''.join(resultado)
    return comprimida if len(comprimida) < len(s) else s

def balanceado(s):
