def titular(s):
    mayusculas = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}
    palabras = s.split()
    resultado = []
    for i, palabra in enumerate(palabras):
        if i == 0:
            resultado.append(palabra.capitalize())
        elif palabra.lower() in mayusculas:
            resultado.append(palabra.lower())
        else:
            resultado.append(palabra.lower().capitalize())
    return ' '.join(resultado)

def aplanar_hasta(lista, profundidad):
    if profundidad == 0:
        return lista
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            resultado.append(elemento)
    return resultado

def sumar_romanos(a, b):
    romanos = ['M', 'CM', 'D', 'CD', 'C', 'XC', 'L', 'XL', 'X', 'IX', 'V', 'IV', 'I']
    valores = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]

    def a_numero(romano):
        resultado = 0
        i = 0
        while i < len(romano):
            if i + 1 < len(romano) and romanos.index(romano[i]) < romanos.index(romano[i + 1]):
                resultado += valores[romanos.index(romano[i + 1])] - valores[romanos.index(romano[i])]
                i += 2
            else:
                resultado += valores[romanos.index(romano[i])]
                i += 1
        return resultado

    def a_romano(numero):
        resultado = ''
        for i in range(len(romanos)):
            while numero >= valores[i]:
                numero -= valores[i]
                resultado += romanos[i]
        return resultado

    return a_romano(a_numero(a) + a_numero(b))

def obtener(d, camino, defecto=None):
    partes = camino.split('.')
    valor = d
    for parte in partes:
        if isinstance(valor, dict) and parte in valor:
            valor = valor[parte]
        else:
            return defecto
    return valor

def con_reintentos(fn, veces):
    ultima_excepcion = None
    for intento in range(veces):
        try:
            return fn()
        except Exception as e:
            ultima_excepcion = e
    raise ultima_excepcion
